"""Four source-reviewed original CARLA RGB cameras for rider encounters."""

from __future__ import annotations

import hashlib
import io
import json
import math
from pathlib import Path
from threading import Condition
import time

from PIL import Image


PROFILE = {"overview": (1920, 1080), "approach": (1280, 720),
           "reference_corner": (1280, 720), "driver_reference": (1280, 720)}


def _transform(carla, raw):
    if not isinstance(raw, dict) or set(raw) != {"x", "y", "z", "pitch", "yaw", "roll"}:
        raise ValueError("six reviewed camera transform coordinates required")
    values = {key: float(value) for key, value in raw.items()}
    if not all(math.isfinite(value) for value in values.values()):
        raise ValueError("reviewed camera transform nonfinite")
    return carla.Transform(
        carla.Location(x=values["x"], y=values["y"], z=values["z"]),
        carla.Rotation(pitch=values["pitch"], yaw=values["yaw"],
                       roll=values["roll"]))


def _validate_transform(raw):
    if not isinstance(raw, dict) or set(raw) != {"x", "y", "z", "pitch", "yaw", "roll"}:
        raise ValueError("six reviewed camera transform coordinates required")
    if not all(math.isfinite(float(value)) for value in raw.values()):
        raise ValueError("reviewed camera transform nonfinite")


def load_review(path, expected_sha256, *, case_id, map_sha256):
    path = Path(path)
    if not path.is_file() or path.is_symlink():
        raise ValueError("reviewed camera source missing")
    if hashlib.sha256(path.read_bytes()).hexdigest() != expected_sha256:
        raise ValueError("reviewed camera source hash drift")
    review = json.loads(path.read_text(encoding="utf-8"))
    if (review.get("format") != "c111260-reviewed-camera-plan-v1"
            or review.get("case_id") != case_id
            or review.get("map_sha256") != map_sha256
            or set(review.get("cameras", {})) != set(PROFILE)):
        raise ValueError("four exact source-reviewed cameras required")
    for name, spec in review["cameras"].items():
        if (spec.get("width"), spec.get("height")) != PROFILE[name]:
            raise ValueError("reviewed camera profile differs")
        if spec.get("attachment") not in ("world", "ego") or not 15 <= float(spec.get("fov_deg", 0)) <= 130:
            raise ValueError("reviewed camera attachment/FOV invalid")
        _validate_transform(spec.get("transform"))
    return review


class OriginalCameras:
    def __init__(self, world, carla, ego, review):
        self.world = world
        self.carla = carla
        self.ego = ego
        self.review = review
        self.sensors = {}
        self.pending = {name: {} for name in PROFILE}
        self.condition = Condition()

    def open(self):
        library = self.world.get_blueprint_library()
        try:
            for name, (width, height) in PROFILE.items():
                spec = self.review["cameras"][name]
                bp = library.find("sensor.camera.rgb")
                if bp is None or bp.id != "sensor.camera.rgb":
                    raise ValueError("original RGB camera blueprint unavailable")
                bp.set_attribute("image_size_x", str(width))
                bp.set_attribute("image_size_y", str(height))
                bp.set_attribute("sensor_tick", "0.05")
                bp.set_attribute("fov", str(spec["fov_deg"]))
                parent = self.ego if spec["attachment"] == "ego" else None
                sensor = self.world.spawn_actor(
                    bp, _transform(self.carla, spec["transform"]), attach_to=parent)
                if sensor is None:
                    raise ValueError("original camera spawn failed: " + name)
                self.sensors[name] = sensor
                sensor.listen(lambda image, view=name: self._on_image(view, image))
            if len({sensor.id for sensor in self.sensors.values()}) != 4:
                raise ValueError("four distinct original camera actors required")
            return self
        except Exception:
            self.close()
            raise

    def _on_image(self, name, image):
        width, height = PROFILE[name]
        if image.width != width or image.height != height or len(image.raw_data) != width * height * 4:
            return
        with self.condition:
            self.pending[name][int(image.frame)] = bytes(image.raw_data)
            self.condition.notify_all()

    def camera_png(self, name, frame, timeout_s=5.0):
        if name not in PROFILE:
            raise ValueError("unknown original camera")
        deadline = time.monotonic() + timeout_s
        with self.condition:
            while frame not in self.pending[name]:
                remaining = deadline - time.monotonic()
                if remaining <= 0:
                    raise ValueError("original camera frame missing: " + name)
                self.condition.wait(remaining)
            raw = self.pending[name].pop(frame)
        image = Image.frombytes("RGBA", PROFILE[name], raw, "raw", "BGRA").convert("RGB")
        target = io.BytesIO()
        image.save(target, format="PNG")
        return target.getvalue()

    def close(self):
        errors = []
        for sensor in self.sensors.values():
            for method in (sensor.stop, sensor.destroy):
                try:
                    method()
                except Exception as error:
                    errors.append(error)
        self.sensors.clear()
        if errors:
            raise RuntimeError("original camera cleanup failed") from errors[0]

    def __enter__(self):
        return self.open()

    def __exit__(self, *_):
        self.close()

"""Attempt-local 20 Hz Native capture with sealed four-camera PNG sources.

The caller owns CARLA world/sensors and supplies synchronous original callbacks.
The capture never labels a fixture physical evidence or infers due care.
"""

import hashlib
import importlib.util
import json
from pathlib import Path
import shutil
from zipfile import ZIP_STORED, ZipFile

from PIL import Image, UnidentifiedImageError

_SPEC = importlib.util.spec_from_file_location("saved_encounter", Path(__file__).with_name("saved_encounter.py"))
_SAVED = importlib.util.module_from_spec(_SPEC)
_SPEC.loader.exec_module(_SAVED)
CAMERAS = _SAVED.CAMERAS
_target = _SAVED._target


FRAMES = 900


def _write_json(root, name, value):
    path = root / name
    path.write_text(json.dumps(value, sort_keys=True, separators=(",", ":")) + "\n", encoding="utf-8")
    return {"path": name, "sha256": hashlib.sha256(path.read_bytes()).hexdigest()}


def capture_attempt(root, *, case_id, site, tick, sample, camera_png, attest_original=False,
                    site_source=None):
    """Capture exactly 900 synchronous ticks and seal original camera images.

    tick returns the original world frame; sample returns original actor state for
    that frame. camera_png returns PNG bytes produced by each named sensor for
    that same frame. A stalled/missing callback aborts instead of filling frames.
    """
    kind, response = _target(case_id)
    root = Path(root)
    root.mkdir(parents=True, exist_ok=True)
    if any(root.iterdir()):
        raise ValueError("attempt directory must be empty")
    if not isinstance(site, dict) or len(site.get("map_sha256", "")) != 64:
        raise ValueError("source-bound site required")
    _SAVED.ENCOUNTER.validate_site(site, kind)
    native_site_ref = None
    if attest_original:
        if not isinstance(site_source, dict) or set(site_source) != {"root", "ref", "world", "carla"}:
            raise ValueError("attested capture requires sealed Native site survey")
        spec = importlib.util.spec_from_file_location("native_site", Path(__file__).with_name("native_site.py"))
        native_site = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(native_site)
        source_root = Path(site_source["root"]).resolve()
        original = native_site.verify_live(site_source["world"], site_source["carla"],
                                           source_root, site_source["ref"], expected_kind=kind)
        if site != original:
            raise ValueError("capture site differs from sealed Native survey")
        for name in ("native-map.xodr", "rider-asset-review.json", "rider-asset.source", "site-survey.json"):
            shutil.copyfile(source_root / name, root / name)
        native_site_ref = {"path": "site-survey.json", "sha256":
                           hashlib.sha256((root / "site-survey.json").read_bytes()).hexdigest()}
    rows = []
    frames = {camera: [] for camera in CAMERAS}
    archives = {}
    writers = {}
    try:
        for camera in CAMERAS:
            name = camera + ".png.zip"
            archives[camera] = name
            writers[camera] = ZipFile(root / name, "w", compression=ZIP_STORED)
        previous = None
        for index in range(FRAMES):
            frame = int(tick())
            if previous is not None and frame != previous + 1:
                raise ValueError("original world tick discontinuity")
            previous = frame
            row = dict(sample(frame))
            if row.get("frame") != frame or row.get("case_id") != case_id:
                raise ValueError("original sample frame or case drift")
            if row.get("source") != "original_native" or row.get("map_sha256") != site["map_sha256"]:
                raise ValueError("original sample/map provenance missing")
            if row.get("rider_kind_observed") != kind:
                raise ValueError("rider classification drift")
            if str(row.get("rider_person_actor_id")) != str(site["rider"]["person_actor_id"]):
                raise ValueError("source-bound rider person identity missing or changed")
            rows.append(row)
            for camera in CAMERAS:
                payload = camera_png(camera, frame)
                if not isinstance(payload, bytes) or not payload.startswith(b"\x89PNG\r\n\x1a\n"):
                    raise ValueError("original camera PNG missing: " + camera)
                writers[camera].writestr(f"{frame:08d}.png", payload)
                frames[camera].append(frame)
    finally:
        for writer in writers.values():
            writer.close()
    _SAVED.ENCOUNTER.audit_original_history(rows, expected_rider_kind=kind,
                                             expected_response=response,
                                             map_sha256=site["map_sha256"],
                                             expected_person_actor_id=site["rider"]["person_actor_id"])
    media = {camera: {"path": archives[camera],
                      "sha256": hashlib.sha256((root / archives[camera]).read_bytes()).hexdigest()}
             for camera in CAMERAS}
    packet = {
        "case_id": case_id, "source": "original_native", "hz": 20,
        "site": _write_json(root, "site.json", site),
        "history": _write_json(root, "history.json", rows),
        "camera_frames": _write_json(root, "camera-frames.json", frames),
        "media": _write_json(root, "media.json", media),
        "capture_origin": "native_adapter_attested" if attest_original else "unreviewed_adapter",
        "native_site": native_site_ref,
        "physical_review": "pending",
        "legal_judgment": "unresolved",
    }
    _write_json(root, "encounter-packet.json", packet)
    return packet


def audit_original_pixels(root, expected_dimensions=None):
    """Reopen every saved PNG and require a complete 4 x 900 frame join."""
    root = Path(root).resolve()
    packet = json.loads((root / "encounter-packet.json").read_text(encoding="utf-8"))
    media_ref = packet.get("media")
    if not isinstance(media_ref, dict) or set(media_ref) != {"path", "sha256"}:
        raise ValueError("sealed media reference missing")
    media_path = root / media_ref["path"]
    if media_path.is_symlink() or media_path.resolve().parent != root:
        raise ValueError("media reference escapes attempt")
    if hashlib.sha256(media_path.read_bytes()).hexdigest() != media_ref["sha256"]:
        raise ValueError("sealed media manifest hash drift")
    media = json.loads(media_path.read_text(encoding="utf-8"))
    if set(media) != set(CAMERAS):
        raise ValueError("four original media archives required")
    frame_ref = packet["camera_frames"]
    frame_path = root / frame_ref["path"]
    if frame_path.is_symlink() or frame_path.resolve().parent != root:
        raise ValueError("camera frame map escapes attempt")
    if hashlib.sha256(frame_path.read_bytes()).hexdigest() != frame_ref["sha256"]:
        raise ValueError("camera frame map hash drift")
    frames = json.loads(frame_path.read_text(encoding="utf-8"))
    for camera in CAMERAS:
        ref = media[camera]
        if set(ref) != {"path", "sha256"}:
            raise ValueError("media source path/hash required")
        path = root / ref["path"]
        if path.is_symlink() or path.resolve().parent != root or path.suffix != ".zip":
            raise ValueError("media archive escapes attempt")
        if hashlib.sha256(path.read_bytes()).hexdigest() != ref["sha256"]:
            raise ValueError("media archive hash drift")
        expected = [f"{int(frame):08d}.png" for frame in frames[camera]]
        if len(expected) != FRAMES or len(set(expected)) != FRAMES:
            raise ValueError("camera frame count or identity drift")
        with ZipFile(path) as archive:
            if archive.namelist() != expected:
                raise ValueError("media frame join drift")
            for name in expected:
                try:
                    with archive.open(name) as source:
                        with Image.open(source) as image:
                            if image.format != "PNG" or min(image.size) <= 0:
                                raise ValueError("invalid original camera image")
                            if expected_dimensions and image.size != tuple(expected_dimensions[camera]):
                                raise ValueError("original camera dimensions differ: " + camera)
                            image.load()
                except (OSError, UnidentifiedImageError) as error:
                    raise ValueError("original camera image decode failed") from error
    return {"format": "worker-original-pixel-audit", "case_id": packet["case_id"],
            "original_frames_per_camera": FRAMES, "decoded_images": FRAMES * len(CAMERAS),
            "media_sha256": {camera: media[camera]["sha256"] for camera in CAMERAS},
            "physical_review": "pending", "legal_judgment": "unresolved"}

"""Source-bound construction and measurement rules for NRS 484B.270(5)(a).

The caller supplies a packet read from a selected Native map and blueprints.
This module never treats requested actors or a scripted brake as observed facts.
"""

from math import hypot, isfinite


RIDER_KINDS = ("bicycle", "electric_bicycle", "electric_scooter")


def _point(entry):
    if not entry.get("source_ref") or not entry.get("road_id") or not entry.get("lane_id"):
        raise ValueError("route waypoint needs original Native provenance")
    result = float(entry["x_m"]), float(entry["y_m"])
    if not all(isfinite(value) for value in result):
        raise ValueError("nonfinite waypoint")
    return result


def _segments_cross(a, b, c, d):
    def side(p, q, r):
        return (q[0] - p[0]) * (r[1] - p[1]) - (q[1] - p[1]) * (r[0] - p[0])
    x, y, z, w = side(a, b, c), side(a, b, d), side(c, d, a), side(c, d, b)
    # OpenDRIVE waypoint sampling commonly places the conflict at a shared
    # segment endpoint. Accept that intersection while rejecting collinear
    # routes, which do not establish an across-path conflict by themselves.
    direction_a = (b[0] - a[0], b[1] - a[1])
    direction_b = (d[0] - c[0], d[1] - c[1])
    cross = direction_a[0] * direction_b[1] - direction_a[1] * direction_b[0]
    return abs(cross) > 1e-6 and x * y <= 0 and z * w <= 0


def validate_site(packet, rider_kind):
    """Reject a tag-only intersection or unsupported rider classification."""
    if rider_kind not in RIDER_KINDS:
        raise ValueError("unsupported rider kind")
    if len(packet.get("map_sha256", "")) != 64 or not packet.get("map_source_ref"):
        raise ValueError("original map hash/source required")
    if packet.get("junction_id") is None:
        raise ValueError("original junction required")
    routes = []
    for name in ("ego_route", "rider_route"):
        entries = packet.get(name, [])
        if len(entries) < 3:
            raise ValueError("approach, conflict and exit waypoints required")
        coordinates = [_point(item) for item in entries]
        if entries[1].get("junction_id") != packet["junction_id"]:
            raise ValueError("route conflict waypoint is outside junction")
        if hypot(coordinates[0][0] - coordinates[1][0], coordinates[0][1] - coordinates[1][1]) < 2:
            raise ValueError("approach too short to establish encounter")
        routes.append(coordinates)
    ego, rider = routes
    if not any(_segments_cross(ego[i], ego[i + 1], rider[j], rider[j + 1])
               for i in range(len(ego) - 1) for j in range(len(rider) - 1)):
        raise ValueError("original routes have no crossing conflict")
    motor = packet.get("motor_vehicle", {})
    if not motor.get("source_ref") or not motor.get("blueprint_id") or motor.get("rail_bound"):
        raise ValueError("source-backed nonrail motor vehicle required")
    rider_actor = packet.get("rider", {})
    if not rider_actor.get("source_ref") or not rider_actor.get("blueprint_id") or not rider_actor.get("person_actor_id"):
        raise ValueError("rider person and blueprint must be source-backed")
    if rider_actor.get("kind") != rider_kind or rider_actor.get("moped"):
        raise ValueError("rider classification conflicts with case")
    if rider_kind == "bicycle":
        wheels = rider_actor.get("wheel_diameters_in", [])
        if len(wheels) != 2 or not any(float(x) > 14 for x in wheels) or rider_actor.get("motorized"):
            raise ValueError("human-powered tandem-wheel bicycle not established")
    elif rider_kind == "electric_bicycle" and not rider_actor.get("electric_assist"):
        raise ValueError("electric bicycle propulsion not established")
    elif rider_kind == "electric_scooter" and not rider_actor.get("standing_platform"):
        raise ValueError("electric scooter platform not established")
    return {"map_sha256": packet["map_sha256"], "junction_id": packet["junction_id"],
            "rider_kind": rider_kind, "crossing_conflict": True}


def spawn_encounter(world, packet, rider_kind, transform_factory):
    """Use source-selected Native blueprints and route approach transforms.

    world is an injected CARLA-shaped object; no CARLA import occurs here.
    Spawn failures clean up both owned actors before returning control.
    """
    validate_site(packet, rider_kind)
    library = world.get_blueprint_library()
    created = []
    try:
        for actor_key, route_key in (("motor_vehicle", "ego_route"), ("rider", "rider_route")):
            blueprint_id = packet[actor_key]["blueprint_id"]
            blueprint = library.find(blueprint_id)
            if blueprint is None or getattr(blueprint, "id", None) != blueprint_id:
                raise ValueError("declared Native blueprint unavailable")
            position = packet[route_key][0]
            actor = world.try_spawn_actor(blueprint, transform_factory(position))
            if actor is None:
                raise ValueError("Native actor spawn failed")
            if getattr(actor, "type_id", None) != blueprint_id:
                raise ValueError("spawned Native actor identity differs")
            created.append(actor)
        return {"ego": created[0], "rider": created[1],
                "blueprint_ids": (created[0].type_id, created[1].type_id)}
    except Exception:
        for actor in reversed(created):
            actor.destroy()
        raise


def control_step(ego_speed_mps, distance_to_conflict_m, rider_time_to_conflict_s, response):
    """Engineering trigger only; no due-care or legal cutoff is inferred."""
    if response not in ("brake", "maintain"):
        raise ValueError("unknown paired response")
    values = (ego_speed_mps, distance_to_conflict_m, rider_time_to_conflict_s)
    if not all(isfinite(float(x)) and float(x) >= 0 for x in values):
        raise ValueError("invalid source samples")
    ego_ttc = float(distance_to_conflict_m) / max(float(ego_speed_mps), 0.01)
    conflict_window = abs(ego_ttc - float(rider_time_to_conflict_s)) <= 2.0
    return {"throttle": 0.0 if response == "brake" and conflict_window else 0.25,
            "brake": 0.65 if response == "brake" and conflict_window else 0.0,
            "conflict_window": conflict_window, "ego_ttc_s": ego_ttc}


def audit_original_history(rows, *, expected_rider_kind, expected_response, map_sha256,
                           expected_person_actor_id=None):
    """Require original samples, role IDs and observed response, never request flags."""
    if expected_rider_kind not in RIDER_KINDS or expected_response not in ("brake", "maintain"):
        raise ValueError("invalid audit target")
    if not rows or len(rows) < 3:
        raise ValueError("insufficient original history")
    first = rows[0]
    expected_ids = (first.get("ego_actor_id"), first.get("rider_actor_id"))
    if not all(expected_ids) or expected_ids[0] == expected_ids[1]:
        raise ValueError("distinct observed actor IDs required")
    if expected_person_actor_id is not None and (
            not first.get("rider_person_actor_id") or
            str(first["rider_person_actor_id"]) != str(expected_person_actor_id) or
            str(first["rider_person_actor_id"]) == str(expected_ids[0])):
        raise ValueError("source-bound rider person identity missing or changed")
    previous = None
    conflict_rows = []
    for row in rows:
        if row.get("source") != "original_native" or row.get("map_sha256") != map_sha256:
            raise ValueError("original map-bound samples required")
        if (row.get("ego_actor_id"), row.get("rider_actor_id")) != expected_ids:
            raise ValueError("actor identity changed")
        if expected_person_actor_id is not None and (
                str(row.get("rider_person_actor_id")) != str(expected_person_actor_id)):
            raise ValueError("source-bound rider person identity missing or changed")
        if row.get("rider_kind_observed") != expected_rider_kind or not row.get("rider_mounted_observed"):
            raise ValueError("rider type or mounted state unobserved")
        frame = int(row["frame"])
        time_s = float(row["time_s"])
        if previous and (frame != previous[0] + 1 or abs(time_s - previous[1] - 0.05) > 0.005):
            raise ValueError("20 Hz original continuity lost")
        previous = frame, time_s
        for key in ("surface_gap_m", "ego_speed_mps", "rider_speed_mps", "ego_brake_observed"):
            if not isfinite(float(row[key])):
                raise ValueError("nonfinite original measurement")
        if row.get("conflict_window_observed"):
            conflict_rows.append(row)
    if not conflict_rows:
        raise ValueError("no observed encounter window")
    brakes = [float(row["ego_brake_observed"]) for row in conflict_rows]
    if expected_response == "brake" and max(brakes) < 0.5:
        raise ValueError("braking response not observed")
    if expected_response == "maintain" and max(brakes) > 0.1:
        raise ValueError("maintained response not observed")
    return {"rider_kind": expected_rider_kind, "response": expected_response,
            "min_surface_gap_m": min(float(row["surface_gap_m"]) for row in conflict_rows),
            "contact_observed": any(bool(row.get("contact_observed")) for row in rows),
            "frames": len(rows), "physical_outcome": "unreviewed"}
